import{_ as a,o as n,c as e,a3 as s}from"./chunks/framework.Ca4XN3PV.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"agent设计/OpenClaw系统提示词.md","filePath":"agent设计/OpenClaw系统提示词.md","lastUpdated":null}'),r={name:"agent设计/OpenClaw系统提示词.md"};function o(d,t,p,l,i,h){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h2 id="openclaw-提示词工程-身份与系统提示词" tabindex="-1">OpenClaw 提示词工程：身份与系统提示词 <a class="header-anchor" href="#openclaw-提示词工程-身份与系统提示词" aria-label="Permalink to &quot;OpenClaw 提示词工程：身份与系统提示词&quot;">​</a></h2><blockquote><p>来源：OpenClaw 官方文档与社区技术拆解。OpenClaw 是一个自托管 AI Agent 网关，将聊天应用（WhatsApp、Telegram、Discord 等）连接到可调用工具的编码智能体，其核心设计理念是“LLM 只负责决策，外部工具负责执行与过滤”。</p></blockquote><h3 id="一、核心定位" tabindex="-1">一、核心定位 <a class="header-anchor" href="#一、核心定位" aria-label="Permalink to &quot;一、核心定位&quot;">​</a></h3><p>OpenClaw 的系统提示词不是运行时默认的一段固定文本，而是<strong>每次智能体运行时动态构建</strong>的结果。人格不在模型权重里——换一份提示词文件，同一个模型就换一种说话方式和行为底线。</p><p><strong>硬约束：短、稳定、每轮都在。</strong> 身份层不是记忆库，也不是技能手册。写长了，模型会把操作细则当性格，把过期事实当人设。</p><h3 id="二、身份材料-拆成四份文件" tabindex="-1">二、身份材料：拆成四份文件 <a class="header-anchor" href="#二、身份材料-拆成四份文件" aria-label="Permalink to &quot;二、身份材料：拆成四份文件&quot;">​</a></h3><p>OpenClaw 将 Agent 的“自我说明”拆成工作区里的 Markdown 文件，每份只回答一个问题：</p><table tabindex="0"><thead><tr><th>文件</th><th>回答</th><th>内容</th></tr></thead><tbody><tr><td><strong>SOUL.md</strong></td><td>你是什么样的人</td><td>性格、语气、沟通风格、行为底线。如“可以有自己的观点”“做那个你真正愿意与之交谈的助手”</td></tr><tr><td><strong>IDENTITY.md</strong></td><td>你叫什么、扮演什么</td><td>名字、角色、语言、emoji 标识等基础身份</td></tr><tr><td><strong>USER.md</strong></td><td>你在帮谁</td><td>用户信息、偏好、背景</td></tr><tr><td><strong>AGENTS.md</strong></td><td>工作步骤</td><td>会话启动流程、记忆使用约定、安全红线、群聊行为规范</td></tr></tbody></table><p>此外，<strong>MEMORY.md</strong> 存放长期事实与决策，<strong>仅在主会话（与用户的直接私聊）中加载</strong>，不在群聊等共享上下文注入。</p><p><strong>组装发生在运行时，不发生在模型内部。</strong> 一轮开始时，运行时按当前场景读出这些文件，拼成身份段，再附上本轮工具名单。</p><h3 id="三、组装结构-三层模型" tabindex="-1">三、组装结构：三层模型 <a class="header-anchor" href="#三、组装结构-三层模型" aria-label="Permalink to &quot;三、组装结构：三层模型&quot;">​</a></h3><p>OpenClaw 的系统提示词按三层组装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Layer 1 · System Prompt 层（静态核心，每次必带）</span></span>
<span class="line"><span>角色定位 / 能力边界 / 安全规则 / 工具指令 / 格式约束 / 行为策略</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>Layer 2 · Workspace 注入层（运行时读取文件）</span></span>
<span class="line"><span>SOUL.md / USER.md / MEMORY.md / AGENTS.md / TOOLS.md</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>Layer 3 · 技能注入层（按需加载）</span></span>
<span class="line"><span>命中技能的 SKILL.md + 相关配置</span></span></code></pre></div><p><strong>优先级规则：</strong> SOUL.md 定义的风格可以覆盖 System Prompt 的默认语气，但 <strong>System Prompt 里的安全规则不能被任何层覆盖</strong>——这在设计层面写死。</p><h3 id="四、按场景注册-不换进程" tabindex="-1">四、按场景注册，不换进程 <a class="header-anchor" href="#四、按场景注册-不换进程" aria-label="Permalink to &quot;四、按场景注册，不换进程&quot;">​</a></h3><p>同一套运行时服务多种场景。每种场景注册两样东西：<strong>一份身份 + 一张该场景允许的执行图</strong>。</p><ul><li>点单场景：有菜单角色和确认订单步骤，没有迎宾导览话术</li><li>迎宾场景：拿不到点单专用节点</li><li>人设文案、表情动作词表：跟场景走，不跟进程走</li></ul><p>新增场景 = 新增一份注册，不是再部署一个进程。身份文件和图的节点名单一起注册，避免“提示词答应了做某件事，图里却没有对应节点”。</p><h3 id="五、什么不该放进身份层" tabindex="-1">五、什么不该放进身份层 <a class="header-anchor" href="#五、什么不该放进身份层" aria-label="Permalink to &quot;五、什么不该放进身份层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不该放</th><th>正确做法</th></tr></thead><tbody><tr><td><strong>整库记忆</strong></td><td>身份段最多写一句“涉及既往事实先去检索”；检索结果由运行时注入</td></tr><tr><td><strong>全部技能步骤</strong></td><td>只留技能名、一句话适用时机、“用到时再读正文”</td></tr><tr><td><strong>领域手册</strong></td><td>写“遇到这类问题去检索”，不粘贴全文</td></tr></tbody></table><p><strong>该放的：换一轮也不会变的规则</strong>——我是谁、在哪种场景、不能越过的线、去哪里取记忆和技能。</p><h3 id="六、边界规则" tabindex="-1">六、边界规则 <a class="header-anchor" href="#六、边界规则" aria-label="Permalink to &quot;六、边界规则&quot;">​</a></h3><p><strong>subagent 不能进一步调用 subagent。</strong></p><h3 id="七、一句话" tabindex="-1">七、一句话 <a class="header-anchor" href="#七、一句话" aria-label="Permalink to &quot;七、一句话&quot;">​</a></h3><blockquote><p>System Prompt 是 OpenClaw Agent 的“出厂设置说明书”：组合身份、记忆、技能、行为规则，告诉它“你是谁、你能干什么、该怎么干”。人格来自 Markdown 文件，不是模型微调——没有秘密配方，只有精心设计的提示词在每条消息前注入系统提示词。</p></blockquote>`,25)])])}const m=a(r,[["render",o]]);export{g as __pageData,m as default};
